package com.example.archive;

import java.nio.file.Path;

/** Where each entry of an uploaded archive is extracted. */
public final class ArchivePaths {
    private ArchivePaths() {
    }

    public static Path destination(Path dest, String entryName) {
        return dest.resolve(entryName);
    }
}

package com.example.archive;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.file.Paths;
import org.junit.jupiter.api.Test;

class ArchivePathsTest {
    @Test
    void joinsEntry() {
        assertEquals(Paths.get("out", "a.txt"), ArchivePaths.destination(Paths.get("out"), "a.txt"));
    }
}
